VALUES
(6001, 6001, 'EMPRESA', 'Apple Premium Reseller (iShop)', 'Distribuidor oficial Apple en Cartagena. MacBooks, iPhones, iPads, Apple Watch y accesorios con garantía internacional.', 'https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901246822-7', 'Apple Premium Reseller (iShop) S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 35 # 71-90', '3037079719', 'Nequi', 4.8, 7, 'ELITE', NOW() - INTERVAL '40 days'),
(6002, 6002, 'EMPRESA', 'Samsung Experience Store', 'Showroom oficial Samsung. Smartphones Galaxy S24, pantallas Neo QLED, tabletas Tab S9 y electrodomésticos inteligentes Bespoke.', 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901179047-1', 'Samsung Experience Store S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 34 # 22-60', '26140494305', 'Banco de Bogotá', 4.9, 5, 'ELITE', NOW() - INTERVAL '43 days'),
(6003, 6003, 'EMPRESA', 'Nike Official Store Cartagena', 'Tienda concepto Nike. Air Jordan, Air Force 1, calzado running Pegasus, indumentaria deportiva y streetwear de alto rendimiento.', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901915104-7', 'Nike Official Store Cartagena S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 32 # 37-42', '3087231939', 'Daviplata', 4.9, 24, 'ELITE', NOW() - INTERVAL '22 days'),
(6004, 6004, 'EMPRESA', 'Adidas Originals & Performance', 'Zapatillas Ultraboost, Samba OG, Stan Smith, ropa de entrenamiento y colaboraciones exclusivas de la marca de las tres rayas.', 'https://images.unsplash.com/photo-1518002171953-a080ee817e1f?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901978960-7', 'Adidas Originals & Performance S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 51 # 27-20', '3065072310', 'Daviplata', 5.0, 13, 'PRO', NOW() - INTERVAL '18 days'),
(6005, 6005, 'EMPRESA', 'Sony Center Caribe', 'Audífonos líderes WH-1000XM5, barras de sonido Dolby Atmos, cámaras profesionales Alpha y accesorios oficiales PlayStation.', 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901788699-8', 'Sony Center Caribe S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 58 # 68-13', '39626153621', 'Davivienda', 4.9, 10, 'PRO', NOW() - INTERVAL '17 days'),
(6006, 6006, 'EMPRESA', 'Decathlon Sports Cartagena', 'Equipamiento para más de 65 deportes: bicicletas de montaña Rockrider, mancuernas Domyos, running Kalenji y senderismo Quechua.', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901527207-1', 'Decathlon Sports Cartagena S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 2 # 74-90', '66275477073', 'Banco de Bogotá', 4.8, 20, 'PRO', NOW() - INTERVAL '29 days'),
(6007, 6007, 'EMPRESA', 'Arturo Calle Menswear', 'Moda masculina ejecutiva y casual. Camisas de lino y algodón pima, trajes de corte italiano, chaquetas y calzado formal.', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901407464-2', 'Arturo Calle Menswear S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 54 # 44-77', '3075948851', 'Nequi', 4.9, 15, 'PRO', NOW() - INTERVAL '8 days'),
(6008, 6008, 'EMPRESA', 'Studio F High Fashion', 'Tendencias en moda femenina contemporánea: vestidos de gala y coctel, blusas frescas, jeans levanta cola y carteras en cuero.', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901306634-6', 'Studio F High Fashion S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 30 # 44-67', '35330075473', 'Davivienda', 5.0, 9, 'PRO', NOW() - INTERVAL '45 days'),
(6009, 6009, 'EMPRESA', 'Sephora Beauty Lounge', 'Cosmética de lujo y perfumería francesa. Fragancias Dior, Chanel, Gucci, paletas Huda Beauty y tratamientos faciales antiedad.', 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901194232-6', 'Sephora Beauty Lounge S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 3 # 59-28', '74695496450', 'Davivienda', 4.8, 14, 'PRO', NOW() - INTERVAL '43 days'),
(6010, 6010, 'EMPRESA', 'IKEA Home & Living', 'Diseño nórdico para el hogar. Sofás modulares, mesas de centro, estanterías funcionales, iluminación cálida y menaje minimalista.', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901815747-4', 'IKEA Home & Living S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 6 # 76-61', '3071540652', 'Nequi', 4.8, 15, 'PRO', NOW() - INTERVAL '29 days'),
(6011, 6011, 'EMPRESA', 'Homecenter Constructor', 'Herramientas eléctricas y manuales Stanley, DeWalt y Bosch. Taladros, sierras, compresores e insumos de remodelación profesional.', 'https://images.unsplash.com/photo-1504148455328-c376907d081c?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901632758-6', 'Homecenter Constructor S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 8 # 59-44', '3015796272', 'Daviplata', 4.8, 19, 'PRO', NOW() - INTERVAL '16 days'),
(6012, 6012, 'EMPRESA', 'Dermatológica Skincare', 'Clínica de la piel y dermocosmética especializada. Protectores solares toque seco, hidratantes CeraVe, sérums de ácido hialurónico y retinol.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901817930-8', 'Dermatológica Skincare S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 41 # 74-4', '53386812712', 'Banco de Bogotá', 4.9, 24, 'PRO', NOW() - INTERVAL '18 days'),
